const calcDias = (cavalo, ref, movimentacoes) => {
  const cavaloId = cavalo.id;
  const inicioMes = new Date(ref.ano, ref.mes - 1, 1);
  const fimMes = new Date(ref.ano, ref.mes, 0);
  const diasTotais = fimMes.getDate();
  const today = new Date(); today.setHours(23, 59, 59, 999);
  const isCurrentMonth = today.getFullYear() === ref.ano && today.getMonth() + 1 === ref.mes;
  const fimEfetivo = isCurrentMonth ? new Date(Math.min(today.getTime(), fimMes.getTime())) : fimMes;

  const cavMovs = (movimentacoes || [])
    .filter(m => m.cavaloId === cavaloId)
    .map(m => ({ ...m, d: new Date(m.data + 'T12:00:00') }))
    .sort((a, b) => a.d - b.d);

  const antes = cavMovs.filter(m => m.d < inicioMes);
  const dentroMes = cavMovs.filter(m => m.d >= inicioMes && m.d <= fimMes);

  // Se tem dataEntrada, usa como referência de presença inicial
  let presente;
  if (cavalo.dataEntrada && !cavMovs.find(m => m.tipo === 'entrada' && m.d < inicioMes)) {
    const dataEntradaDate = new Date(cavalo.dataEntrada + 'T00:00:00');
    presente = dataEntradaDate < inicioMes;
  } else {
    presente = antes.length > 0 ? antes[antes.length - 1].tipo === 'entrada' : true;
  }

  if (dentroMes.length === 0) {
    if (presente) {
      let dataInicio = new Date(inicioMes);
      if (cavalo.dataEntrada && !cavMovs.find(m => m.tipo === 'entrada' && m.d < inicioMes)) {
        const dataEntradaDate = new Date(cavalo.dataEntrada + 'T00:00:00');
        if (dataEntradaDate > inicioMes) dataInicio = dataEntradaDate;
      }
      const diasEfetivos = Math.floor((fimEfetivo - dataInicio) / (1000 * 60 * 60 * 24)) + 1;
      return { dias: Math.min(Math.max(diasEfetivos, 0), diasTotais), total: diasTotais, parcial: true };
    }
    // Não estava presente no início do mês — mas pode ter entrado no mês via dataEntrada (sem movimentação)
    if (cavalo.dataEntrada) {
      const dataEntradaDate = new Date(cavalo.dataEntrada + 'T00:00:00');
      if (dataEntradaDate >= inicioMes && dataEntradaDate <= fimEfetivo) {
        const diasEfetivos = Math.floor((fimEfetivo - dataEntradaDate) / (1000 * 60 * 60 * 24)) + 1;
        return { dias: Math.min(Math.max(diasEfetivos, 0), diasTotais), total: diasTotais, parcial: true };
      }
    }
    return { dias: 0, total: diasTotais, parcial: true };
  }

  let dias = 0;
  let cursor = new Date(inicioMes);
  for (const m of dentroMes) {
    if (presente) {
      dias += Math.max(0, Math.floor((m.d - cursor) / (1000 * 60 * 60 * 24)) + (m.tipo === 'saida' ? 1 : 0));
    }
    presente = m.tipo === 'entrada';
    cursor = new Date(m.d);
  }
  if (presente) {
    dias += Math.max(0, Math.floor((fimEfetivo - cursor) / (1000 * 60 * 60 * 24)) + 1);
  }
  return { dias: Math.min(dias, diasTotais), total: diasTotais, parcial: true };
};

// Cavalo só aparece em fatura/cálculo do mês se: teve dias de presença OU
// teve algum registro/procedimento dentro do mês. Animais que já saíram em meses
// anteriores e sem atividade no mês corrente são descartados.
const cavaloAtivoNoMes = (cav, ref, movimentacoes, registros = [], procedimentos = []) => {
  const { dias } = calcDias(cav, ref, movimentacoes);
  if (dias > 0) return true;
  const checaData = (s) => {
    if (!s) return false;
    const d = new Date(s + 'T12:00:00');
    return d.getFullYear() === ref.ano && d.getMonth() + 1 === ref.mes;
  };
  for (const r of registros) if (r.cavaloId === cav.id && checaData(r.data)) return true;
  for (const p of procedimentos) if (p.cavaloId === cav.id && checaData(p.data)) return true;
  return false;
};

const calcDiasItem = (cav, ref, movimentacoes, dataInicio, dataFim) => {
  if (!dataInicio && !dataFim) return calcDias(cav, ref, movimentacoes).dias;
  const inicioMes = new Date(ref.ano, ref.mes - 1, 1);
  const fimMes = new Date(ref.ano, ref.mes, 0);
  const today = new Date(); today.setHours(23, 59, 59, 999);
  const rangeS = dataInicio ? new Date(dataInicio + 'T00:00:00') : inicioMes;
  const rangeE = dataFim ? new Date(dataFim + 'T00:00:00') : fimMes;
  const efStart = rangeS > inicioMes ? rangeS : inicioMes;
  const efEndRaw = rangeE < fimMes ? rangeE : fimMes;
  const efEnd = new Date(Math.min(efEndRaw.getTime(), today.getTime()));
  if (efEnd < efStart) return 0;
  const cavaloId = cav.id;
  const cavMovs = (movimentacoes || [])
    .filter(m => m.cavaloId === cavaloId)
    .map(m => ({ ...m, d: new Date(m.data + 'T12:00:00') }))
    .sort((a, b) => a.d - b.d);
  const antes = cavMovs.filter(m => m.d < efStart);
  const dentroPeriodo = cavMovs.filter(m => m.d >= efStart && m.d <= efEnd);
  let presente;
  if (cav.dataEntrada && !cavMovs.find(m => m.tipo === 'entrada' && m.d < efStart)) {
    presente = new Date(cav.dataEntrada + 'T00:00:00') < efStart;
  } else {
    presente = antes.length > 0 ? antes[antes.length - 1].tipo === 'entrada' : true;
  }
  if (dentroPeriodo.length === 0) {
    if (presente) {
      let contStart = new Date(efStart);
      if (cav.dataEntrada && !cavMovs.find(m => m.tipo === 'entrada' && m.d < efStart)) {
        const ent = new Date(cav.dataEntrada + 'T00:00:00');
        if (ent > efStart) contStart = ent;
      }
      if (contStart > efEnd) return 0;
      return Math.max(0, Math.floor((efEnd - contStart) / 86400000) + 1);
    }
    // Não estava presente no início do período — pode ter entrado dentro dele via dataEntrada
    if (cav.dataEntrada) {
      const ent = new Date(cav.dataEntrada + 'T00:00:00');
      if (ent >= efStart && ent <= efEnd) {
        return Math.max(0, Math.floor((efEnd - ent) / 86400000) + 1);
      }
    }
    return 0;
  }
  let dias = 0;
  let cursor = new Date(efStart);
  for (const m of dentroPeriodo) {
    if (presente) dias += Math.max(0, Math.floor((m.d - cursor) / 86400000) + (m.tipo === 'saida' ? 1 : 0));
    presente = m.tipo === 'entrada';
    cursor = new Date(m.d);
  }
  if (presente) dias += Math.max(0, Math.floor((efEnd - cursor) / 86400000) + 1);
  return dias;
};

const calcMensalidadeProporcional = (cav, ref, movimentacoes) => {
  const { dias, total, parcial } = calcDias(cav, ref, movimentacoes);
  const rawBase = Number(cav.mensalidade);
  const valorBase = Number.isFinite(rawBase) ? rawBase : 0;
  return { dias, total, parcial, valor: total > 0 ? valorBase * (dias / total) : 0, valorBase };
};

// Conta quantas doses de um insumo periódico ocorrem no mês de referência,
// considerando presença do cavalo (movimentacoes + dataEntrada) e a data
// de início/fim do programa. Semanal/Quinzenal usam diaSemana como âncora;
// quinzenal mantém o ciclo de 14 dias ancorado em dataInicio se houver.
const calcDosesPeriodico = (p, ref, cav, movimentacoes) => {
  const inicioMes = new Date(ref.ano, ref.mes - 1, 1);
  const fimMes = new Date(ref.ano, ref.mes, 0);
  const today = new Date(); today.setHours(23, 59, 59, 999);
  const isCurrentMonth = today.getFullYear() === ref.ano && today.getMonth() + 1 === ref.mes;
  const fimEfetivo = isCurrentMonth ? new Date(Math.min(today.getTime(), fimMes.getTime())) : new Date(fimMes);
  const dataInicioP = p.dataInicio ? new Date(p.dataInicio + 'T00:00:00') : null;
  const dataFimP = p.dataFim ? new Date(p.dataFim + 'T00:00:00') : null;
  const effStart = new Date(Math.max((dataInicioP || inicioMes).getTime(), inicioMes.getTime()));
  const effEnd = new Date(Math.min((dataFimP || fimEfetivo).getTime(), fimEfetivo.getTime()));
  if (effEnd < effStart) return 0;

  const freqDias = p.frequencia === 'quinzenal' ? 14 : p.frequencia === 'semanal' ? 7 :
    p.frequencia === 'diario' ? 1 : p.frequencia?.startsWith('cada') ? (parseInt(p.frequencia.replace('cada', '')) || 7) : 7;

  const cavMovs = cav ? (movimentacoes || [])
    .filter(m => m.cavaloId === cav.id)
    .map(m => ({ ...m, d: new Date(m.data + 'T12:00:00') }))
    .sort((a, b) => a.d - b.d) : [];
  const cavPresenteEm = (target) => {
    if (!cav) return true;
    const t = new Date(target); t.setHours(12, 0, 0, 0);
    let presente = true;
    if (cav.dataEntrada) presente = new Date(cav.dataEntrada + 'T00:00:00') <= t;
    for (const m of cavMovs) {
      if (m.d > t) break;
      presente = m.tipo === 'entrada';
    }
    return presente;
  };

  let cursor = new Date(effStart);
  if (p.frequencia === 'semanal' || p.frequencia === 'quinzenal') {
    const targetDay = p.diaSemana != null ? p.diaSemana : cursor.getDay();
    if (p.frequencia === 'quinzenal' && dataInicioP) {
      const anchor = new Date(dataInicioP);
      const anchorOffset = (targetDay - anchor.getDay() + 7) % 7;
      anchor.setDate(anchor.getDate() + anchorOffset);
      while (anchor < effStart) anchor.setDate(anchor.getDate() + freqDias);
      cursor = anchor;
    } else {
      const offset = (targetDay - cursor.getDay() + 7) % 7;
      cursor.setDate(cursor.getDate() + offset);
    }
  }

  let doses = 0;
  while (cursor <= effEnd) {
    if (cavPresenteEm(cursor)) doses++;
    cursor.setDate(cursor.getDate() + freqDias);
  }
  return doses;
};

const _labelFreq = (freq) => {
  if (freq === 'quinzenal') return 'quinzenal';
  if (freq === 'semanal') return 'semanal';
  if (freq === 'diario') return 'diário';
  if (freq?.startsWith('cada')) return `cada ${freq.replace('cada', '')}d`;
  return '';
};

const calcPerfilMes = (cav, ref, movimentacoes, insumos) => {
  const { dias } = calcDias(cav, ref, movimentacoes);
  if (!cav.nutricao || dias === 0) return { linhas: [], total: 0, dias };
  const findIns = (id) => (insumos || []).find(i => i.id === id);
  // Potro ao pé e "pagar o custo" pagam tudo (inclusive ração/feno/sal),
  // pois não pagam mensalidade que cobre esses insumos
  const ehPotroAoPe = (cav.categorias || []).includes('Potro ao pé') || cav.categoria === 'Potro ao pé';
  const pagaCusto = !!cav.pagarOCusto || ehPotroAoPe;
  const isIncluso = (ins) => !pagaCusto && (!!ins?.incluidoMensalidade || ins?.categoria === 'nutricao_base' || ins?.categoria === 'racao');
  const linhas = [];

  // Ração e feno — só adicionados quando paga o custo (potro ao pé / pagarOCusto)
  if (pagaCusto) {
    // Ração
    if (cav.nutricao.racaoId) {
      const racao = findIns(cav.nutricao.racaoId);
      const kgDia = (cav.nutricao.racaoKgManha || 0) + (cav.nutricao.racaoKgTarde || 0) + (cav.nutricao.comeAlmoco ? (cav.nutricao.racaoKgAlmoco || 0) : 0);
      if (racao && kgDia > 0) {
        linhas.push({ insumoId: racao.id, nome: racao.nome, qtdDia: kgDia, unidade: racao.unidade || 'kg', valorUnit: racao.valorVenda || 0, valorDia: (racao.valorVenda || 0) * kgDia, valorMes: (racao.valorVenda || 0) * kgDia * dias, dias });
      }
    }
    // Feno
    if ((cav.nutricao.fenoKgDia || 0) > 0) {
      const feno = (insumos || []).find(i => i.nome?.toLowerCase().includes('feno'));
      if (feno) linhas.push({ insumoId: feno.id, nome: feno.nome, qtdDia: cav.nutricao.fenoKgDia, unidade: feno.unidade || 'kg', valorUnit: feno.valorVenda || 0, valorDia: (feno.valorVenda || 0) * cav.nutricao.fenoKgDia, valorMes: (feno.valorVenda || 0) * cav.nutricao.fenoKgDia * dias, dias });
    }
    // Sal Kromium — nutrição base (cobrado só quando paga custo, igual ração/feno)
    const _salKgDia = (Number(cav.nutricao.salKromiumGManha) || 0) + (Number(cav.nutricao.salKromiumGTarde) || 0);
    if (_salKgDia > 0) {
      const sal = (insumos || []).find(i => /sal/i.test(i.nome || '') && /kromium/i.test(i.nome || ''));
      if (sal) linhas.push({ insumoId: sal.id, nome: sal.nome, qtdDia: _salKgDia, unidade: sal.unidade || 'g', valorUnit: sal.valorVenda || 0, valorDia: (sal.valorVenda || 0) * _salKgDia, valorMes: (sal.valorVenda || 0) * _salKgDia * dias, dias });
    }
  }

  if (cav.nutricao.oleoMlDia > 0) {
    const oleoIns = findIns('i_oleo') || (insumos || []).find(i => i.nome?.toLowerCase().includes('óleo') || i.nome?.toLowerCase().includes('oleo'));
    if (oleoIns && !isIncluso(oleoIns)) linhas.push({ insumoId: oleoIns.id, nome: oleoIns.nome, qtdDia: cav.nutricao.oleoMlDia, unidade: oleoIns.unidade, valorUnit: oleoIns.valorVenda, valorDia: oleoIns.valorVenda * cav.nutricao.oleoMlDia, valorMes: oleoIns.valorVenda * cav.nutricao.oleoMlDia * dias, tipoLinha: 'nutricional', diasUsados: dias, dias });
  }
  for (const s of (cav.nutricao.suplementos || [])) {
    const ins = findIns(s.insumoId);
    if (!ins || isIncluso(ins)) continue;
    const diasEfetivos = calcDiasItem(cav, ref, movimentacoes, s.dataInicio, s.dataFim);
    linhas.push({ insumoId: ins.id, nome: ins.nome, qtdDia: s.qtdDia, unidade: ins.unidade, valorUnit: ins.valorVenda, valorDia: ins.valorVenda * s.qtdDia, valorMes: ins.valorVenda * s.qtdDia * diasEfetivos, dias: diasEfetivos });
  }
  for (const p of (cav.nutricao.periodicos || [])) {
    const ins = findIns(p.insumoId);
    if (!ins || isIncluso(ins)) continue;
    const doses = calcDosesPeriodico(p, ref, cav, movimentacoes);
    if (doses === 0) continue;
    const dosePorVez = Number(p.qtd) || 0;
    const qtdMes = dosePorVez * doses;
    linhas.push({
      insumoId: ins.id,
      nome: ins.nome + ' (periódico)',
      qtdDia: dosePorVez, // dose por administração (não é mais média/dia)
      qtdMes,
      dosesMes: doses,
      unidade: ins.unidade,
      valorUnit: ins.valorVenda,
      valorMes: (Number(ins.valorVenda) || 0) * qtdMes,
      dias: doses, // compat: nº de doses no mês
      periodico: true,
      freqLabel: _labelFreq(p.frequencia),
    });
  }
  return { linhas, total: linhas.reduce((s, l) => s + l.valorMes, 0), dias };
};

// ─────────────────────────────────────────────────────────────
// CÁLCULO ÚNICO DE FATURA — fonte da verdade
// Usado por FaturaLista, FaturaDetalhe, Resumo, auto-fechar e Próxima fatura.
// Mantém a regra:
//   total = mensalidade + perfilNutricional + insumosAvulsos + procedimentos + custoFixoRateado
// Cobra cota = valor / shareCount(cavalo)
// Filtros de insumos:
//   - se cavalo paga o custo (potroAoPe ou pagarOCusto): TODOS os insumos entram
//   - se NÃO paga: pula insumos com incluidoMensalidade=true ou categoria ração/nutricao_base
// Custo fixo: só cobra de cavalos pagarOCusto, proporcional aos dias.
// ─────────────────────────────────────────────────────────────
const _ehPotroAoPe = (c) => (c.categorias || []).includes('Potro ao pé') || c.categoria === 'Potro ao pé';
const _cavPagaCusto = (c) => !!c?.pagarOCusto || _ehPotroAoPe(c || {});
const _shareCount = (c) => Math.max(1, (c?.proprietarioIds || []).length || 1);
// Share considerando a data específica (rateio entre coproprietários
// vigentes naquela data). Fallback: share atual.
const _shareCountEmData = (c, dataIso) => {
  const donos = donosEmData(c, dataIso);
  return Math.max(1, donos.length || 1);
};

// Verifica se propId era um dos donos do cavalo em algum momento
// do mês ref (via historicoProprietarios).
const _foiDonoNoMes = (cavalo, propId, ref) => {
  const periodos = periodosProprietariosNoMes(cavalo, ref);
  return periodos.some(p => p.propIds.includes(propId));
};

const calcFaturaProprietario = (propId, ref, deps) => {
  const { cavalos = [], registros = [], procedimentos = [], servicos = [], insumos = [], movimentacoes = [], custosFixos = [] } = deps;
  // Considera cavalo se propId foi dono em qualquer momento do mês
  const cavalosObj = cavalos
    .filter(c => _foiDonoNoMes(c, propId, ref))
    .filter(c => cavaloAtivoNoMes(c, ref, movimentacoes, registros, procedimentos));
  const cavIds = new Set(cavalosObj.map(c => c.id));
  const findInsumo = (iid) => insumos.find(i => i.id === iid);

  // Mensalidade — potros ao pé / pagarOCusto não pagam.
  // Se cavalo teve transferência no mês, o valor é rateado
  // proporcionalmente aos dias em que propId foi dono.
  const propMens = cavalosObj.map(c => {
    const share = _shareCount(c);
    if (_cavPagaCusto(c)) {
      const dd = calcDias(c, ref, movimentacoes);
      return { cav: c, dias: dd.dias, total: dd.total, valor: 0, valorBase: 0, share, parcial: false };
    }
    const base = { cav: c, ...calcMensalidadeProporcional(c, ref, movimentacoes), share };
    // Rateio por período de titularidade dentro do mês
    const diasComoProp = diasComoProprietarioNoMes(c, propId, ref);
    const diasTotais = calcDias(c, ref, movimentacoes).dias;
    if (diasTotais > 0 && diasComoProp < diasTotais) {
      // Ajusta o valor: cobra só a fração de dias em que propId era dono.
      // Fração calculada sobre os dias do mês (não sobre dias estabulados).
      base.valorBase = base.valor;
      base.valor = base.valor * (diasComoProp / diasTotais);
      base.diasComoProp = diasComoProp;
      base.transferido = true;
    }
    return base;
  });
  const mensTotal = propMens.reduce((s, m) => s + m.valor / m.share, 0);

  // Perfil nutricional — calcPerfilMes já trata pagaCusto internamente.
  // Também aplica rateio se cavalo teve transferência.
  const propPerfil = cavalosObj
    .map(c => {
      const share = _shareCount(c);
      const base = { cav: c, ...calcPerfilMes(c, ref, movimentacoes, insumos), share };
      const diasComoProp = diasComoProprietarioNoMes(c, propId, ref);
      const diasTotais = calcDias(c, ref, movimentacoes).dias;
      if (diasTotais > 0 && diasComoProp < diasTotais) {
        base.total = base.total * (diasComoProp / diasTotais);
        base.linhas = base.linhas.map(l => ({ ...l, valorMes: (l.valorMes ?? l.valor ?? 0) * (diasComoProp / diasTotais) }));
        base.transferido = true;
        base.diasComoProp = diasComoProp;
      }
      return base;
    })
    .filter(pp => pp.linhas.length > 0 && pp.total > 0);
  const perfilTotal = propPerfil.reduce((s, pp) => s + pp.total / pp.share, 0);

  // Insumos avulsos — cada registro vai pro dono na data do registro.
  const myReg = registros.filter(r => {
    if (!cavIds.has(r.cavaloId)) return false;
    // Filtra pela titularidade na data do registro
    const cav = cavalosObj.find(x => x.id === r.cavaloId);
    const donos = donosEmData(cav, r.data);
    if (!donos.includes(propId)) return false;
    const ins = findInsumo(r.insumoId);
    const paga = _cavPagaCusto(cav);
    // r.cobrarAvulso força cobrança mesmo se insumo é incluidoMensalidade
    // ou categoria ração/nutrição (uso: entrega na saída do haras)
    if (!paga && !r.cobrarAvulso) {
      if (ins?.incluidoMensalidade) return false;
      if (ins?.categoria === 'nutricao_base' || ins?.categoria === 'racao') return false;
    }
    if (!r.data) return true;
    const d = new Date(r.data + 'T12:00:00');
    return d.getFullYear() === ref.ano && d.getMonth() + 1 === ref.mes;
  });
  const insumosLinhas = myReg.map(r => {
    const ins = findInsumo(r.insumoId);
    const cav = cavalos.find(c => c.id === r.cavaloId);
    const share = _shareCountEmData(cav, r.data);
    const subtotal = (Number(ins?.valorVenda) || 0) * r.qtd;
    return { reg: r, ins, cav, subtotal, total: subtotal / share, share };
  });
  const insumosTotal = insumosLinhas.reduce((s, l) => s + l.total, 0);

  // Procedimentos avulsos — vai pro dono na data do procedimento.
  const procLinhas = procedimentos.filter(pr => {
    if (!cavIds.has(pr.cavaloId)) return false;
    if (!pr.data) return false;
    const cav = cavalosObj.find(x => x.id === pr.cavaloId);
    const donos = donosEmData(cav, pr.data);
    if (!donos.includes(propId)) return false;
    const d = new Date(pr.data + 'T12:00:00');
    return d.getFullYear() === ref.ano && d.getMonth() + 1 === ref.mes;
  }).map(pr => {
    const cav = cavalos.find(c => c.id === pr.cavaloId);
    const sv = servicos.find(s => s.id === pr.servicoId);
    const share = _shareCountEmData(cav, pr.data);
    const nomeSv = pr.servicoId === '__exames_lab__' ? 'Exames laboratoriais' : (sv?.nome || 'Procedimento');
    return { proc: pr, cav, sv, nomeSv, share, total: (Number(pr.total) || 0) / share };
  });
  const procedimentosTotal = procLinhas.reduce((s, l) => s + l.total, 0);

  // Custo fixo rateado — só cobra de cavalos pagarOCusto
  const mesKey = `${ref.ano}-${String(ref.mes).padStart(2, '0')}`;
  const CATEGORIAS_RATEAVEIS = ['salario', 'contabilidade', 'energia', 'internet', 'extras'];
  const cfDoMes = (custosFixos || []).filter(c => c.mes === mesKey);
  const cfActuals = cfDoMes.reduce((s, c) => (CATEGORIAS_RATEAVEIS.includes(c.categoria) ? s + (Number(c.valor) || 0) : s), 0);
  const cfProvisao = cfDoMes.filter(c => c.categoria === 'salario').reduce((s, c) => s + (Number(c.valor) || 0) * (Number(c.encargosPct) || 0) / 100, 0);
  const cfTotalMes = cfActuals + cfProvisao;
  const nPagantesHaras = cavalos.filter(c => c.presente !== false && !_ehPotroAoPe(c)).length;
  const cfPorCavaloMes = nPagantesHaras > 0 ? cfTotalMes / nPagantesHaras : 0;
  const cfLinhas = cavalosObj
    .filter(c => !!c.pagarOCusto)
    .map(c => {
      const { dias, total: totalDias } = calcDias(c, ref, movimentacoes);
      const share = _shareCount(c);
      let valorTotal = cfPorCavaloMes * (totalDias > 0 ? dias / totalDias : 0);
      const diasComoProp = diasComoProprietarioNoMes(c, propId, ref);
      let transferido = false;
      if (dias > 0 && diasComoProp < dias) {
        valorTotal = valorTotal * (diasComoProp / dias);
        transferido = true;
      }
      return { cav: c, dias, totalDias, diasComoProp, transferido, share, valor: valorTotal / share, cotaMensal: cfPorCavaloMes };
    });
  const custoFixoTotal = cfLinhas.reduce((s, l) => s + l.valor, 0);

  const total = mensTotal + perfilTotal + insumosTotal + procedimentosTotal + custoFixoTotal;
  return {
    cavalosObj, total,
    mensalidades: mensTotal, perfilNutricional: perfilTotal,
    insumosAvulsos: insumosTotal, procedimentosAvulsos: procedimentosTotal,
    custoFixoRateado: custoFixoTotal,
    propMens, propPerfil, insumosLinhas, procLinhas, cfLinhas,
    cfPorCavaloMes,
  };
};

// Versão "custo real" do perfil nutricional: usa valorCompra (com fallback p/ valorVenda).
// Sempre inclui ração, feno, óleo, suplementos e periódicos — para o haras, todo
// consumo é gasto real, independente de "incluído na mensalidade".
const calcCustoCompraPerfilMes = (cav, ref, movimentacoes, insumos) => {
  const { dias } = calcDias(cav, ref, movimentacoes);
  if (!cav.nutricao || dias === 0) return { linhas: [], total: 0, dias };
  const findIns = (id) => (insumos || []).find(i => i.id === id);
  const v = (ins) => Number(ins?.valorCompra ?? ins?.valorVenda ?? 0) || 0;
  const linhas = [];
  if (cav.nutricao.racaoId) {
    const racao = findIns(cav.nutricao.racaoId);
    const kgDia = (cav.nutricao.racaoKgManha || 0) + (cav.nutricao.racaoKgTarde || 0) + (cav.nutricao.comeAlmoco ? (cav.nutricao.racaoKgAlmoco || 0) : 0);
    if (racao && kgDia > 0) linhas.push({ nome: racao.nome, valorMes: v(racao) * kgDia * dias });
  }
  if ((cav.nutricao.fenoKgDia || 0) > 0) {
    const feno = (insumos || []).find(i => i.nome?.toLowerCase().includes('feno'));
    if (feno) linhas.push({ nome: feno.nome, valorMes: v(feno) * cav.nutricao.fenoKgDia * dias });
  }
  if (cav.nutricao.oleoMlDia > 0) {
    const oleoIns = findIns('i_oleo') || (insumos || []).find(i => i.nome?.toLowerCase().includes('óleo') || i.nome?.toLowerCase().includes('oleo'));
    if (oleoIns) linhas.push({ nome: oleoIns.nome, valorMes: v(oleoIns) * cav.nutricao.oleoMlDia * dias });
  }
  const _salKgDiaC = (Number(cav.nutricao.salKromiumGManha) || 0) + (Number(cav.nutricao.salKromiumGTarde) || 0);
  if (_salKgDiaC > 0) {
    const sal = (insumos || []).find(i => /sal/i.test(i.nome || '') && /kromium/i.test(i.nome || ''));
    if (sal) linhas.push({ nome: sal.nome, valorMes: v(sal) * _salKgDiaC * dias });
  }
  for (const s of (cav.nutricao.suplementos || [])) {
    const ins = findIns(s.insumoId);
    if (!ins) continue;
    const diasEf = calcDiasItem(cav, ref, movimentacoes, s.dataInicio, s.dataFim);
    linhas.push({ nome: ins.nome, valorMes: v(ins) * s.qtdDia * diasEf });
  }
  for (const p of (cav.nutricao.periodicos || [])) {
    const ins = findIns(p.insumoId);
    if (!ins) continue;
    const freqDias = p.frequencia === 'quinzenal' ? 14 : p.frequencia === 'semanal' ? 7 : p.frequencia === 'diario' ? 1 : p.frequencia?.startsWith('cada') ? parseInt(p.frequencia.replace('cada', '')) || 7 : 7;
    const qtdDia = p.qtd / freqDias;
    const diasEf = calcDiasItem(cav, ref, movimentacoes, p.dataInicio, p.dataFim);
    linhas.push({ nome: ins.nome + ' (per.)', valorMes: v(ins) * qtdDia * diasEf });
  }
  return { linhas, total: linhas.reduce((s, l) => s + l.valorMes, 0), dias };
};

